/**
 * One version of one view: either a template plus configuration, or generated or hand-written code. Only approved versions are served to readers; until then the block's fallback is shown.
 *
 */
export interface ViewSpec {
  view_id: ViewId;
  version: string;
  tenant_id: TenantId;
  title: string;
  template_id?: ViewTemplateId;
  template_version?: string;
  /**
   * Template options, validated by the template.
   */
  template_config?: {};
  code?: BlobRef;
  data_schema: {};
  capabilities: ViewCapability[];
  status: ViewStatus;
  render_report?: RenderReport;
  approval_todo_id?: TodoId;
  created_by: PrincipalId;
  created_at: Instant;
  decided_by?: PrincipalId;
  decided_at?: Instant;
  rejection_reason?: string;
}
/**
 * A reusable view shipped with the product (SOP step navigator, decision tree, comparison matrix...). The bundle is one HTML file with inline CSS and JS.
 *
 */
export interface ViewTemplate {
  id: ViewTemplateId;
  version: string;
  title: string;
  description?: string;
  capabilities: ViewCapability[];
  /**
   * JSON Schema of the payload the view expects in insp.init and insp.data.
   */
  data_schema: {};
  bundle: BlobRef;
}
